function AdminView({ locale, email, threads, onReply }: { locale:Locale; email:string; threads:SupportThread[]; onReply:(threadId:string,text:string)=>void }) {
  type AdminPost = { id:string; author:string; caption:string; createdAt:string; image?:string; likes?:string[]; comments?:unknown[] };
  const [posts,setPosts]=useState<AdminPost[]>([]);
  const [selectedThread,setSelectedThread]=useState("");
  const [reply,setReply]=useState("");
  useEffect(()=>{setPosts(read<AdminPost[]>("hf:posts",[]));},[]);
  const activeThread=threads.find((thread)=>thread.id===selectedThread)??threads[0];
  function removePost(id:string){const next=posts.filter((post)=>post.id!==id);setPosts(next);save("hf:posts",next);}
  function submitReply(event:FormEvent){event.preventDefault();if(!activeThread||!reply.trim())return;onReply(activeThread.id,reply);setReply("");}
  return <><PageIntro eyebrow="ADMIN" title={t(locale,"Admin dashboard")} subtitle={t(locale,"Manage local demo content and review community posts.")}/><section className="admin-account-card"><span className="admin-shield">⚙</span><div><b>{t(locale,"Demo administrator")}</b><small>{email} · {t(locale,"Local demo only — this is not protected by server authentication.")}</small></div><span className="status-chip">ADMIN</span></section><div className="stats-grid admin-stats"><article className="stat-card"><span>◎ {t(locale,"Community posts")}</span><b>{posts.length}</b><small>{t(locale,"saved in this browser")}</small></article><article className="stat-card"><span>👥 {t(locale,"Friends")}</span><b>{read<Friend[]>("hf:friends",demoFriends).length}</b><small>{t(locale,"local profiles")}</small></article><article className="stat-card"><span>✉ {t(locale,"Support messages")}</span><b>{threads.reduce((total,thread)=>total+thread.messages.length,0)}</b><small>{threads.length} {t(locale,"conversations")}</small></article><article className="stat-card"><span>🔒 {t(locale,"Access")}</span><b>{t(locale,"Demo")}</b><small>{t(locale,"Browser only")}</small></article></div><section className="panel admin-inbox-panel"><div className="panel-heading"><div><span className="eyebrow">{t(locale,"Support inbox")}</span><h2>{t(locale,"Messages from users")}</h2></div><span className="count-pill">{threads.length}</span></div>{threads.length?<div className="admin-inbox-layout"><div className="admin-thread-list">{threads.map((thread)=><button key={thread.id} className={activeThread?.id===thread.id?"admin-thread-select selected":"admin-thread-select"} onClick={()=>setSelectedThread(thread.id)}><b>{thread.name}</b><small>{thread.email||t(locale,"Guest user")}</small><span>{thread.messages[thread.messages.length-1]?.text||""}</span></button>)}</div>{activeThread&&<div className="admin-thread-detail"><div className="admin-thread-title"><div><b>{activeThread.name}</b><small>{activeThread.email||t(locale,"Guest user")}</small></div><span className="status-chip">{t(locale,"User")}</span></div><div className="support-thread-messages admin-thread-messages">{activeThread.messages.map((message)=><article className={`support-thread-message ${message.sender}`} key={message.id}><b>{message.sender==="admin"?t(locale,"Administrator"):activeThread.name}</b><p>{message.text}</p><time>{new Date(message.createdAt).toLocaleString(locale==="kk"?"kk-KZ":locale==="ru"?"ru-RU":"en-US",{dateStyle:"medium",timeStyle:"short"})}</time></article>)}</div><form className="support-compose" onSubmit={submitReply}><textarea value={reply} onChange={(event)=>setReply(event.target.value)} placeholder={t(locale,"Write a reply…")} maxLength={1000} required/><div><small>{t(locale,"Reply as admin")}</small><button className="button primary" type="submit">➤ {t(locale,"Send reply")}</button></div></form></div>}</div>:<div className="support-thread-empty"><span>📭</span><b>{t(locale,"No support messages yet")}</b><p>{t(locale,"User messages will appear here.")}</p></div>}</section><section className="panel admin-posts-panel"><div className="panel-heading"><div><span className="eyebrow">{t(locale,"Moderation")}</span><h2>{t(locale,"Community posts")}</h2></div><span className="count-pill">{posts.length}</span></div>{posts.length?posts.map((post)=><article className="admin-post-row" key={post.id}>{post.image&&<img src={post.image} alt=""/>}<div><b>{post.author}</b><p>{post.caption||t(locale,"Photo post")}</p><small>{new Date(post.createdAt).toLocaleDateString()}</small></div><button className="text-button danger" onClick={()=>removePost(post.id)}>{t(locale,"Remove post")}</button></article>):<div className="empty-state"><span>🗂️</span><b>{t(locale,"No community posts yet")}</b><p>{t(locale,"Posts from this browser will appear here for moderation.")}</p></div>}</section><p className="local-note">{t(locale,"Admin controls only affect this browser. A real admin account needs a server and secure sign-in.")}</p></>;
}

